const createItemPool = (create, sync, destroy) => {
    const items = new Map();
    const used = new Set();
    return {
        beginRender: () => {
            used.clear();
        },
        get: (key) => {
            used.add(key);
            let item = items.get(key);
            if (item === undefined) {
                item = create();
                items.set(key, item);
            }
            return item;
        },
        endRender: () => {
            for (const [key, item] of items) {
                if (used.has(key)) {
                    sync(item);
                }
                else {
                    destroy(item);
                    items.delete(key);
                }
            }
        },
        destroy: () => {
            for (const item of items.values()) {
                destroy(item);
            }
            items.clear();
            used.clear();
        },
    };
};

export { createItemPool as c };
